def translate_program(text, unroll_bounded=False):
    """Parse and encode ``text``; return ``(ast, encoder)``."""
    ast = parse_program(text)
    encoder = HornEncoder(unroll_bounded=unroll_bounded)
    encoder.encode_program(ast)
    return ast, encoder


class HornVerifier(object):
    """Translate an imperative program and decide its safety with Spacer."""

    def __init__(self, text, unroll_bounded=False):
        self.text = text
        self.unroll_bounded = unroll_bounded
        self.ast = None
        self.encoder = None
        self.fp = None
        self.answer = None

    def translate(self):
        """Parse + encode + build the Z3 fixedpoint (no solving yet)."""
        self.ast, self.encoder = translate_program(self.text, self.unroll_bounded)
        self.encoder.validate_clauses()
        self.fp = self.encoder.to_z3()
        return self.encoder

    def verify(self):
        """Return ``{"safe", "num_clauses", "num_relations", ...}``."""
        if self.encoder is None:
            self.translate()
        result = self.fp.query(self.encoder.error())
        safe = result == z3.unsat
        invariants = {}
        if safe:
            try:
                self.answer = self.fp.get_answer()
                definitions = extract_relation_definitions(self.answer)
            except z3.Z3Exception:  # pragma: no cover - defensive
                definitions = {}
            for relation in self.encoder.loop_relations:
                definition = definitions.get(relation.name())
                if definition is not None:
                    invariants[relation.name()] = str(z3.simplify(definition))
        return {
            "safe": safe,
            "result": str(result),
            "num_clauses": self.encoder.num_clauses,
            "num_relations": self.encoder.num_relations,
            "num_loops": len(self.encoder.loop_relations),
            "loop_invariants": invariants,
            "variables": list(self.encoder.program_vars),
        }


def verify_program(text):
    """Parse, encode and verify an imperative program in one call."""
    return HornVerifier(text).verify()


# ===========================================================================
# 5. Benchmark programs
# ===========================================================================

PROGRAMS = [
    ("simple_counter", """
        // count up to ten, then check we landed exactly on ten
        var x = 0;
        while (x < 10) { x = x + 1; }
        assert(x == 10)
    """),
    ("sum_accumulator", """
        var s = 0;
        var i = 0;
        while (i < 5) {
            s = s + i;
            i = i + 1;
        }
        assert(s >= 0)
    """),
    ("branch_test", """
        var x = 5;
        if (x > 3) { x = x - 1; } else { x = x + 1; }
        assert(x >= 0)
    """),
    ("unsafe_loop", """
        // x leaves the loop at 100, so x < 50 must fail
        var x = 0;
        while (x < 100) { x = x + 2; }
        assert(x < 50)
    """),
    ("nested_arithmetic", """
        var a = 1;
        var b = 2;
        a = a + b;
        b = a * 2;
        assert(b == 6)
    """),
]


def run_translation_batch(programs=None):
    """Translate and verify every program, returning a metrics dictionary."""
    programs = PROGRAMS if programs is None else programs
    total_clauses = 0
    verified = 0
    unsafe = 0
    invariants = 0
    translation_time = 0.0
    details = []

    for name, text in programs:
        verifier = HornVerifier(text)
        start = time.time()
        encoder = verifier.translate()
        translation_time += time.time() - start
        total_clauses += encoder.num_clauses

        result = verifier.verify()
        if result["safe"]:
            verified += 1
        else:
            unsafe += 1
        invariants += len(result["loop_invariants"])
        result["name"] = name
        details.append(result)

    return {
        "HORN_CLAUSES_GENERATED": total_clauses,
        "HORN_PROGRAMS_VERIFIED": verified,
        "HORN_PROGRAMS_UNSAFE": unsafe,
        "HORN_LOOP_INVARIANTS": invariants,
        "HORN_TRANSLATION_TIME": round(translation_time, 2),
        "details": details,
    }
